public class AVLTree { static class N{int k,h;N l,r;N(int k){this.k=k;}} N root; int h(N n){return n==null?-1:n.h;} int bf(N n){return n==null?0:h(n.l)-h(n.r);} void upd(N n){n.h=1+Math.max(h(n.l),h(n.r));} N rotateRight(N y){N x=y.l;y.l=x.r;x.r=y;upd(y);upd(x);return x;} N rotateLeft(N x){N y=x.r;x.r=y.l;y.l=x;upd(x);upd(y);return y;} public void insert(int k){root=ins(root,k);} N ins(N n,int k){if(n==null)return new N(k);if(k<n.k)n.l=ins(n.l,k);else if(k>n.k)n.r=ins(n.r,k);upd(n);if(bf(n)>1&&k<n.l.k)return rotateRight(n);if(bf(n)<-1&&k>n.r.k)return rotateLeft(n);if(bf(n)>1){n.l=rotateLeft(n.l);return rotateRight(n);}if(bf(n)<-1){n.r=rotateRight(n.r);return rotateLeft(n);}return n;} boolean ok(){return ok(root);} boolean ok(N n){return n==null||Math.abs(bf(n))<=1&&ok(n.l)&&ok(n.r);} public static void run(){AVLTree t=new AVLTree();for(int x:new int[]{30,20,10,25,40,50})t.insert(x);System.out.println("AVL root="+t.root.k+", invariant="+t.ok()+", root balance="+t.bf(t.root));System.out.println("Deletion teaching note: remove as in BST, then rebalance while returning toward the root.\n");} public static void main(String[] args){run();}}
